WITH cleaned AS (SELECT *, DATEDIFF(end_date, start_date) AS days_start_date_to_end_date, CASE WHEN plan IN ('basic', 'premium') THEN 'Core' ELSE 'Other' END AS plan_group FROM subscriptions WHERE customer_id IS NOT NULL) SELECT *, PERCENT_RANK() OVER (ORDER BY days_start_date_to_end_date DESC NULLS LAST) AS days_start_date_to_end_date_percent_rank, LAG(days_start_date_to_end_date, 2) OVER (PARTITION BY status ORDER BY start_date, id) AS prev_days_start_date_to_end_date, NTILE(3) OVER (PARTITION BY customer_id ORDER BY monthly_fee, id) AS monthly_fee_bucket, ROW_NUMBER() OVER (PARTITION BY plan, customer_id ORDER BY start_date, id) AS seq_no FROM cleaned;
